"use client"

import { useMemo, useState } from "react"

import { Button } from "@/components/ui/button"
import {
  Card,
  CardContent,
  CardDescription,
  CardFooter,
  CardHeader,
  CardTitle,
} from "@/components/ui/card"
import { Input } from "@/components/ui/input"
import { Textarea } from "@/components/ui/textarea"
import { cn } from "@/lib/utils"

export type FormCardField =
  | {
      name: string
      label: string
      type: "text" | "date" | "textarea"
      required?: boolean
      placeholder?: string
    }
  | {
      name: string
      label: string
      type: "number"
      required?: boolean
      placeholder?: string
      min?: number
      max?: number
    }
  | {
      name: string
      label: string
      type: "select"
      required?: boolean
      options: { label: string; value: string }[]
    }
  | { name: string; label: string; type: "toggle"; required?: boolean }

export type FormCardProps = {
  title: string
  description?: string
  submitLabel?: string
  fields: FormCardField[]
  isLoading?: boolean
  isDisabled?: boolean
  error?: {
    title: string
    description?: string
  }
  onSubmit?: (values: Record<string, string | number | boolean>) => void
}

export function FormCard({
  title,
  description,
  submitLabel = "Submit",
  fields = [],
  isLoading,
  isDisabled,
  error,
  onSubmit,
}: FormCardProps) {
  const initialValues = useMemo<
    Record<string, string | number | boolean>
  >(() => {
    return Object.fromEntries(
      fields.map((field) => [field.name, field.type === "toggle" ? false : ""])
    )
  }, [fields])
  const [editedValues, setEditedValues] =
    useState<Record<string, string | number | boolean>>(initialValues)
  const values = useMemo(() => {
    const next = { ...initialValues }

    for (const field of fields) {
      if (field.name in editedValues) {
        next[field.name] = editedValues[field.name]
      }
    }

    return next
  }, [editedValues, fields, initialValues])
  const formDisabled = Boolean(isDisabled || isLoading || error || !onSubmit)
  const isUnavailable = Boolean(!onSubmit && !isDisabled && !isLoading && !error)

  function setValue(name: string, value: string | number | boolean) {
    setEditedValues((current) => ({ ...current, [name]: value }))
  }

  return (
    <Card
      className="w-full max-w-2xl"
      data-fable-ui="form-card"
      aria-busy={isLoading || undefined}
    >
      <CardHeader>
        <CardTitle className="text-base">{title || "Collect input"}</CardTitle>
        {description ? <CardDescription>{description}</CardDescription> : null}
      </CardHeader>
      <CardContent>
        {isLoading ? (
          <p role="status" className="text-sm text-muted-foreground">
            Preparing form...
          </p>
        ) : null}
        {error ? (
          <div
            className="mb-4 rounded-md border border-destructive/20 bg-destructive/5 p-3"
            role="alert"
          >
            <p className="text-sm font-medium text-destructive">
              {error.title}
            </p>
            {error.description ? (
              <p className="text-sm text-muted-foreground">
                {error.description}
              </p>
            ) : null}
          </div>
        ) : null}
        {isUnavailable ? (
          <p role="status" className="mb-4 text-sm text-muted-foreground">
            Form submission is unavailable.
          </p>
        ) : null}
        <form
          className="flex flex-col gap-4"
          onSubmit={(event) => {
            event.preventDefault()
            onSubmit?.(values)
          }}
        >
          {fields.map((field) => {
            const value = values[field.name]

            return (
              <label
                key={field.name}
                className={cn("flex flex-col gap-2 text-sm font-medium", {
                  "flex-row-reverse items-center justify-end":
                    field.type === "toggle",
                })}
              >
                <span>{field.label}</span>
                {field.type === "textarea" ? (
                  <Textarea
                    value={String(value ?? "")}
                    placeholder={field.placeholder}
                    required={field.required}
                    disabled={formDisabled}
                    onChange={(event) =>
                      setValue(field.name, event.target.value)
                    }
                  />
                ) : field.type === "select" ? (
                  <select
                    className="h-9 rounded-md border bg-background px-3 text-sm"
                    value={String(value ?? "")}
                    required={field.required}
                    disabled={formDisabled}
                    onChange={(event) =>
                      setValue(field.name, event.target.value)
                    }
                  >
                    <option value="">Select...</option>
                    {field.options.map((option) => (
                      <option key={option.value} value={option.value}>
                        {option.label}
                      </option>
                    ))}
                  </select>
                ) : field.type === "toggle" ? (
                  <input
                    type="checkbox"
                    checked={Boolean(value)}
                    required={field.required}
                    disabled={formDisabled}
                    onChange={(event) =>
                      setValue(field.name, event.target.checked)
                    }
                  />
                ) : (
                  <Input
                    type={field.type}
                    value={String(value ?? "")}
                    min={field.type === "number" ? field.min : undefined}
                    max={field.type === "number" ? field.max : undefined}
                    placeholder={field.placeholder}
                    required={field.required}
                    disabled={formDisabled}
                    onChange={(event) =>
                      setValue(
                        field.name,
                        field.type === "number" && event.target.value !== ""
                          ? Number(event.target.value)
                          : event.target.value
                      )
                    }
                  />
                )}
              </label>
            )
          })}
          <CardFooter className="px-0 pb-0">
            <Button
              type="submit"
              disabled={formDisabled || fields.length === 0}
            >
              {submitLabel}
            </Button>
          </CardFooter>
        </form>
      </CardContent>
    </Card>
  )
}

import { tool } from "ai"
import { z } from "zod"

import { defineFableComponent } from "@/lib/fable-ui/core/definitions"
import { FormCard } from "@/components/fable-ui/form-card/form-card"

const baseField = {
  name: z.string().min(1),
  label: z.string().min(1),
  required: z.boolean().optional(),
  placeholder: z.string().optional(),
}

const collectInputFieldSchema = z.discriminatedUnion("type", [
  z.object({ ...baseField, type: z.literal("text") }).strict(),
  z.object({ ...baseField, type: z.literal("date") }).strict(),
  z.object({ ...baseField, type: z.literal("textarea") }).strict(),
  z
    .object({
      ...baseField,
      type: z.literal("number"),
      min: z.number().optional(),
      max: z.number().optional(),
    })
    .strict(),
  z
    .object({
      ...baseField,
      type: z.literal("select"),
      options: z
        .array(
          z
            .object({ label: z.string().min(1), value: z.string().min(1) })
            .strict()
        )
        .min(1)
        .max(12),
    })
    .strict(),
  z.object({ ...baseField, type: z.literal("toggle") }).strict(),
])

export const collectInputSchema = z
  .object({
    title: z.string().min(1),
    description: z.string().optional(),
    submitLabel: z.string().min(1).optional(),
    fields: z.array(collectInputFieldSchema).min(1).max(8),
  })
  .strict()

export const collectInputToolSchema = collectInputSchema.describe(
  "One to eight fields. Valid field types are text, number, select, date, textarea, and toggle. Select fields require non-empty string options."
)

export type CollectInput = z.infer<typeof collectInputSchema>
export type CollectInputToolInput = z.infer<typeof collectInputToolSchema>

export function createCollectInputTool() {
  return tool({
    description:
      "Collect a few structured fields mid-conversation. Keep forms short; valid payloads need title and fields. The host must validate submitted values.",
    inputSchema: collectInputToolSchema,
  })
}

export const collectInput = defineFableComponent({
  name: "collect_input",
  schema: collectInputSchema,
  tool: createCollectInputTool(),
  renderer: {
    Component: FormCard,
    loadingProps: { title: "Collect input", fields: [], isLoading: true },
    emptyProps: { title: "Collect input", fields: [] },
    errorProps: (description: string) => ({
      title: "Form unavailable",
      fields: [],
      error: { title: "Form unavailable", description },
    }),
    toProps: (data: CollectInput, handlers) => ({
      ...data,
      onSubmit: handlers.onFormSubmit,
    }),
  },
})
